package io.camunda.application;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

/**
 * The shipped config/defaults.yaml is committed but generated from the Spring configuration
 * metadata of the configuration module. Nothing else fails when the two drift apart.
 *
 * <p>Gradle and Maven pass the file generated by the configuration module through the {@value
 * #GENERATED_PROPERTY} system property. The test fails when the file was not generated, e.g. when
 * running dist without the configuration module in the same Maven reactor. Local builds copy the
 * generated file over the committed one, so only CI can catch a stale commit.
 *
 * <p>If this fails on a diff you did not cause, the generated file is probably wrong, not the
 * committed one: the configuration processor writes spring-configuration-metadata.json from the
 * sources it compiles, so a partial recompile of the configuration module in Maven drops the
 * properties of untouched classes. The module therefore forces full recompiles, but a stale {@code
 * configuration/target} from an older build can still bite. Run {@code mvn clean install -pl
 * configuration -Dquickly} and retry before touching the committed file.
 */
@EnabledIfSystemProperty(named = DefaultConfigTest.GENERATED_PROPERTY, matches = ".+")
class DefaultConfigTest {

  static final String GENERATED_PROPERTY = "camunda.test.generated-defaults-yaml";
  private static final Path DEFAULTS_YAML = Path.of("src/main/config/defaults.yaml");

  @Test
  void shouldShipDefaultsYamlIdenticalToTheGeneratedOne() {
    // given the defaults.yaml generated by the configuration module
    final var generated = Path.of(System.getProperty(GENERATED_PROPERTY));
    assertThat(generated)
        .describedAs("%s was not generated, build :configuration", generated)
        .exists();

    // when comparing it with the committed one
    // then they are byte for byte the same
    assertThat(DEFAULTS_YAML)
        .describedAs(
            "%s is outdated, regenerate it with './gradlew :camunda-zeebe:updateDefaultConfig'"
                + " or 'mvn process-resources -pl dist/' (both run automatically outside CI)",
            DEFAULTS_YAML)
        .hasSameBinaryContentAs(generated);
  }
}
